INSERT INTO dump_descriptions (base_key, description) VALUES ('coilgunparticles', 'Restores the Coil Gun’s particle effects for players who want its visuals while using other particle-removal mods.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('enns_biome_schmorp', 'Raises Nitra-generation odds in Magma, Shallow, and Ossuary biomes, and removes native stationary spawns from Ossuary so Custom Difficulty 2 can manage them.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('flammablegasfix', 'Bundles Steeve visibility improvements with a pak that reverts the Praetorian gas fix.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('spawnparticles', 'Restores enemy spawn particles; load it above particle-removal mods.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('white_biomes', 'Changes the main cave-rock material to white and uses neutral-gray fog, giving caves a pale biome look.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('removeunwantedassetchanges', 'Restores selected base-game visuals altered by the Azuki-San lootbug, flare, and flare-gun-ammo mods, including Space Rig holograms and loading-screen Hoxxes.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('skinpack', 'Adds 352 custom paintjobs, about 60 distinct designs excluding recolors; most are animated and require Custom Vanity Framework.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('spacerigtweaks', 'Darkens the Space Rig by removing extra lights from the drop pod and terminals while keeping many ambient point lights; also removes Forge and drop-pod drill smoke.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
